def f(g):
    H,W=len(g),len(g[0])
    cnt=collections.Counter(v for r in g for v in r)
    bg=cnt.most_common(1)[0][0]
    pts=[(i,j) for i in range(H) for j in range(W) if g[i][j]!=bg]
    out=[r[:] for r in g]
    def sgn(x): return (1 if x>0 else -1 if x!=0 else 0)
    def component(p):
        st=[p]; c=set()
        while st:
            a,b=st.pop()
            if (a,b) in c: continue
            c.add((a,b)); st.extend([(a+da,b+db) for da in(-1,0,1) for db in(-1,0,1) if 0<=a+da<H and 0<=b+db<W and g[a+da][b+db]!=bg and (a+da,b+db)!=p])
        return c
    seen=set(); groups=[]
    for p in pts:
        if p in seen: continue
        comp=component(p); seen|=comp; groups.append(comp)
    res=set()
    for grp in groups:
        if len(grp)<2: continue
        grp=sorted(grp)
        dy,dx=sgn(grp[-1][0]-grp[0][0]),sgn(grp[-1][1]-grp[0][1])
        walk=lambda start,d: [walk0(start,d)] or None
        def walk0(start,d):
            stack=[start]; vis={start}
            while stack:
                p=stack.pop()
                nr,nc=p[0]+d[0],p[1]+d[1]
                if not(0<=nr<H and 0<=nc<W): continue
                if g[nr][nc]==bg:
                    if g[nr][nc]==bg: pass
                    if (nr,nc) not in vis and g[nr][nc]==bg:
                        vis.add((nr,nc)); stack.append((nr,nc))
                elif (nr,nc) not in vis and (nr,nc) not in grp:
                    # obstacle -> reflect dx
                    nnd=(d[0],-d[1])
                    nn,mm=nr+nnd[0],nc+nnd[1]
                    if 0<=nn<H and 0<=mm<W:
                        if g[nn][mm]==bg:
                            vis.add((nn,mm)); stack.append((nn,mm))
                        elif (nn,mm) not in grp:
                            pass
        # simpler iterative
        def ray(start,d):
            path=[]; p=start
            while True:
                nr,nc=p[0]+d[0],p[1]+d[1]
                if not(0<=nr<H and 0<=nc<W): break
                if g[nr][nc]==bg:
                    out[nr][nc]=3; path.append((nr,nc)); p=(nr,nc); continue
                if (nr,nc) in grp: break
                d2=(d[0],-d[1])
                nn,nm=nr+d2[0],nc+d2[1]
                if not(0<=nn<H and 0<=nm<W): break
                if g[nn][nm]==bg:
                    d=d2; p=(nn,nm)
                else: break
            return path
        for start,d in [(grp[0],(dy,dx)),(grp[-1],(-dy,-dx))]:
            path=ray(start,d)
            res|set(path)
    print(res)
